import { useAppStore } from "@/store";
import { Card } from "@/shared/ui/data/Card";
import { Button } from "@/shared/ui/controls/Button";
import { Box } from "@/shared/ui/layout/Box";
import { SettingsPageHeader } from "@/features/settings/pages/SettingsPageHeader";

const prose: React.CSSProperties = { fontFamily: "var(--sans)", fontSize: 12, lineHeight: 1.6, color: "var(--fg-muted)" };

export function AutomationsPage() {
  const setWorkspace = useAppStore((s) => s.setWorkspace);
  const setProjectsPageMode = useAppStore((s) => s.setProjectsPageMode);
  return (
    <Box style={{ maxWidth: 820 }}>
      <SettingsPageHeader
        title="Automations"
        description="How scheduled automations run against your console sessions."
        descMb={22}
      />

      <Card title="Automations">
        <Box style={prose}>
          <p style={{ margin: "0 0 10px 0" }}>
            An <strong>automation</strong> is a cron-triggered rule that dispatches a command into a
            specified console pane. An always-on background scheduler fires armed automations at their
            next run time and records each run.
          </p>
          <p style={{ margin: "0 0 14px 0" }}>
            Schedules are carried by the PERSONA that runs them — authored with `bsc persona set`,
            read on the Teams page, and their run history is on Logs.
          </p>
          {/* The Automations workspace is retired (hooks-and-schedules-belong-to-the-persona):
              schedules are carried by the persona that runs them and read on Teams, and run
              history is the Logs -> Automations tab. */}
          <Button onClick={() => { setWorkspace("projects"); setProjectsPageMode("teams"); }}>Open Teams →</Button>
        </Box>
      </Card>
    </Box>
  );
}
